10	// claudeHarnessWithAliases builds a claude subscription harness where
11	// AutoRoutingModels carries the bare aliases produced by
12	// subprocessHarnessAutoRoutingModels before the catalog-surface override
13	// replaces them. ModelEligibility is deliberately configured to resolve the
14	// "haiku" alias to ExactPinOnly=true so the gate fires correctly.
15	func claudeHarnessWithAliases() Inputs {
16		return Inputs{
17			Harnesses: []HarnessEntry{{
18				Name:                "claude",
19				Surface:             "claude",
20				CostClass:           "medium",
21				IsSubscription:      true,
22				AutoRoutingEligible: true,
23				ExactPinSupport:     true,
24				Available:           true,
25				QuotaOK:             true,
26				SubscriptionOK:      true,
27				SupportsTools:       true,
28				DefaultModel:        "sonnet-4.6",
29				// AutoRoutingModels carries both the surface IDs (post-catalog-override
30				// form) and the bare alias "haiku" to simulate the pre-override state
31				// that triggers the alias gate miss.
32				SupportedModels:   []string{"sonnet-4.6", "haiku-5.5", "haiku"},
33				AutoRoutingModels: []string{"sonnet-4.6", "haiku"},
34				Providers: []ProviderEntry{{
35					Billing:       modelcatalog.BillingModelSubscription,
36					CostSource:    CostSourceSubscription,
37					SupportsTools: true,
38					CostUSDPer1kTokensByModel: map[string]float64{
39						"sonnet-4.6": 0.009,
40						"haiku-5.5":  0.002,
41						"haiku":      0.002,
42					},
43				}},
44			}},
45			// ModelEligibility resolves both the surface ID "haiku-5.5" and the bare
46			// alias "haiku" to ExactPinOnly=true so the gate fires for either form.
47			ModelEligibility: func(model string) (ModelEligibility, bool) {
48				switch model {
49				case "sonnet-4.6", "claude-sonnet-4-6":
50					return ModelEligibility{Power: 8, AutoRoutable: true}, true
51				case "haiku-5.5", "claude-haiku-5.5", "haiku":
52					return ModelEligibility{Power: 7, ExactPinOnly: true, AutoRoutable: false}, true
53				default:
54					return ModelEligibility{}, false
55				}
56			},
57			Now: time.Date(2026, 5, 31, 0, 0, 0, 0, time.UTC),
58		}
59	}
