61	// TestHaikuLowTierNotAutoRoutedForDefaultPolicy is AC1: an unpinned
62	// policy=default request on the claude harness MUST NOT select the haiku/low
63	// tier even when "haiku" (the bare alias) appears in AutoRoutingModels. The
64	// middle-tier sonnet must win. This guards the exact_pin_only invariant from
65	// FEAT-004 phase-1: haiku is only reachable via an explicit model pin.
66	func TestHaikuLowTierNotAutoRoutedForDefaultPolicy(t *testing.T) {
67		in := claudeHarnessWithAliases()
68	
69		dec, err := Resolve(Request{Policy: "default"}, in)
70		if err != nil {
71			t.Fatalf("Resolve policy=default: %v", err)
72		}
73		if dec.Harness != "claude" || dec.Model != "sonnet-4.6" {
74			t.Errorf("policy=default: selected %s/%s, want claude/sonnet-4.6", dec.Harness, dec.Model)
75		}
76	
77		// haiku must appear in the candidates list with eligible=false and
78		// FilterReasonExactPinOnly so the routing_decision trace is observable.
79		haikuFound := false
80		for _, c := range dec.Candidates {
81			if c.Harness != "claude" {
82				continue
83			}
84			if c.Model != "haiku" && c.Model != "haiku-5.5" {
85				continue
86			}
87			haikuFound = true
88			if c.Eligible {
89				t.Errorf("claude/%s Eligible=true; haiku must not be auto-routed (exact_pin_only)", c.Model)
90			}
91			if c.FilterReason != FilterReasonExactPinOnly {
92				t.Errorf("claude/%s FilterReason=%q, want %q", c.Model, c.FilterReason, FilterReasonExactPinOnly)
93			}
94		}
95		if !haikuFound {
96			t.Errorf("claude/haiku row missing from routing_decision candidates; got %v",
97				func() []string {
98					var names []string
99					for _, c := range dec.Candidates {
100						names = append(names, c.Harness+"/"+c.Model)
101					}
102					return names
103				}())
104		}
105	}
