107	// TestHaikuAliasEligibilityLookupReturnsExactPinOnly is AC2: the
108	// ModelEligibility lookup for the bare claude low-tier alias "haiku" must
109	// resolve ExactPinOnly=true. This is the gate that prevents haiku from winning
110	// automatic routing when a request carries no explicit power bounds.
111	func TestHaikuAliasEligibilityLookupReturnsExactPinOnly(t *testing.T) {
112		in := claudeHarnessWithAliases()
113		lookup := in.ModelEligibility
114	
115		cases := []struct {
116			alias string
117		}{
118			{"haiku"},
119			{"haiku-5.5"},
120			{"claude-haiku-5.5"},
121		}
122		for _, tc := range cases {
123			elig, ok := lookup(tc.alias)
124			if !ok {
125				t.Errorf("ModelEligibility(%q): ok=false; want ExactPinOnly=true (gate must fire)", tc.alias)
126				continue
127			}
128			if !elig.ExactPinOnly {
129				t.Errorf("ModelEligibility(%q).ExactPinOnly=false; want true", tc.alias)
130			}
131			if elig.AutoRoutable {
132				t.Errorf("ModelEligibility(%q).AutoRoutable=true; want false (low tier is pin-only)", tc.alias)
133			}
134		}
135	}
136	
137	// TestHaikuOnlyReachableViaExplicitModelPin asserts that pinning
138	// --model haiku (or --model haiku-5.5) is still honoured by the routing
139	// engine even though haiku is exact-pin-only. The explicit Model pin bypasses
140	// the auto-routing eligibility gate per CheckPowerEligibility contract.
141	func TestHaikuOnlyReachableViaExplicitModelPin(t *testing.T) {
142		in := claudeHarnessWithAliases()
143	
144		for _, pin := range []string{"haiku", "haiku-5.5"} {
145			dec, err := Resolve(Request{Model: pin}, in)
146			if err != nil {
147				t.Fatalf("Resolve --model %q: %v", pin, err)
148			}
149			if dec.Model != pin {
150				t.Errorf("--model %q: selected model=%q, want %q", pin, dec.Model, pin)
151			}
152		}
153	}
