1	package modelcatalog
2	
3	import (
4		"strconv"
5		"strings"
6	)
7	
8	// Tier classifies a model within its family by capability level.
9	type Tier int
10	
11	const (
12		TierSmart    Tier = 0 // unsuffixed gpt, opus claude, pro gemini
13		TierStandard Tier = 1 // mini gpt, sonnet claude, flash gemini
14		TierCheap    Tier = 2 // nano gpt, haiku claude, flash-lite gemini
15		TierUnknown  Tier = 99
16	)
17	
18	// FamilyTiers maps family name to a map of tier-suffix → Tier.
19	var FamilyTiers = map[string]map[string]Tier{
20		"gpt":    {"": TierSmart, "mini": TierStandard, "nano": TierCheap},
21		"claude": {"opus": TierSmart, "sonnet": TierStandard, "haiku": TierCheap},
22		"gemini": {"pro": TierSmart, "flash": TierStandard, "flash-lite": TierCheap},
23	}
24	
25	// ParsedModel holds the structured components of a parsed model ID.
26	type ParsedModel struct {
27		Family     string // "gpt", "claude", "gemini", ...
28		Version    []int  // [5, 5] for gpt-5.5; [4, 7] for opus-4.7; normalized so [5] -> [5, 0]
29		Tier       Tier   // smart/standard/cheap/unknown
30		PreRelease bool   // true for "preview", "alpha", etc.
31		Raw        string // original ID
32	}
33	
34	var preReleaseSuffixes = map[string]bool{
35		"preview": true,
36		"alpha":   true,
37		"beta":    true,
38		"rc":      true,
39	}
40	
41	var claudeTierNames = map[string]bool{
42		"opus": true, "sonnet": true, "haiku": true,
43	}
44	
45	// Parse parses a model ID string into its structured components.
46	// Does not panic on any input; unknown families return {Family: "<prefix>", Tier: TierUnknown}.
47	func Parse(id string) ParsedModel {
48		raw := id
49		lower := strings.ToLower(strings.TrimSpace(id))
50		if lower == "" {
51			return ParsedModel{Family: "", Tier: TierUnknown, Raw: raw}
52		}
53		parts := strings.Split(lower, "-")
54		switch parts[0] {
55		case "gpt":
56			return parseGPT(parts[1:], raw)
57		case "claude":
58			return parseClaudeWithPrefix(parts[1:], raw)
59		case "gemini":
60			return parseGemini(parts[1:], raw)
61		default:
62			if claudeTierNames[parts[0]] {
63				return parseClaudeShort(parts[0], parts[1:], raw)
64			}
65			return ParsedModel{Family: parts[0], Tier: TierUnknown, Raw: raw}
66		}
67	}
68	
69	// Compare returns a negative int when a should rank before b ("a is better"),
70	// positive when b should rank before a, and 0 when equal or cross-family.
71	// Ranking: newer version > older; within version, TierSmart > TierStandard > TierCheap > TierUnknown;
72	// within tier, GA > pre-release.
73	func (a ParsedModel) Compare(b ParsedModel) int {
74		if a.Family != b.Family {
75			return 0
76		}
77		// Higher version ranks first → negate the slice comparison result.
78		if vCmp := compareVersionSlices(a.Version, b.Version); vCmp != 0 {
79			return -vCmp
80		}
81		if a.Tier != b.Tier {
82			if a.Tier < b.Tier {
83				return -1
84			}
85			return 1
86		}
87		if a.PreRelease != b.PreRelease {
88			if !a.PreRelease {
89				return -1 // GA ranks before pre-release
90			}
91			return 1
92		}
93		return 0
94	}
95	
96	func parseGPT(tokens []string, raw string) ParsedModel {
97		if len(tokens) == 0 {
98			return ParsedModel{Family: "gpt", Tier: TierUnknown, Raw: raw}
99		}
100		version := parseDottedVersion(tokens[0])
101		if version == nil {
102			return ParsedModel{Family: "gpt", Tier: TierUnknown, Raw: raw}
103		}
104		tier, pre := parseGPTSuffix(tokens[1:])
105		return ParsedModel{
106			Family:     "gpt",
107			Version:    normalizeVersion(version),
108			Tier:       tier,
109			PreRelease: pre,
110			Raw:        raw,
111		}
112	}
113	
114	func parseGPTSuffix(tokens []string) (Tier, bool) {
115		preRelease := false
116		remaining := append([]string(nil), tokens...)
117		for len(remaining) > 0 && preReleaseSuffixes[remaining[len(remaining)-1]] {
118			preRelease = true
119			remaining = remaining[:len(remaining)-1]
120		}
121		if len(remaining) == 0 {
122			return TierSmart, preRelease
123		}
124		suffix := strings.Join(remaining, "-")
125		if t, ok := FamilyTiers["gpt"][suffix]; ok {
126			return t, preRelease
127		}
128		return TierUnknown, preRelease
129	}
130	
131	func parseClaudeWithPrefix(tokens []string, raw string) ParsedModel {
132		if len(tokens) == 0 {
133			return ParsedModel{Family: "claude", Tier: TierUnknown, Raw: raw}
134		}
135		tier, ok := FamilyTiers["claude"][tokens[0]]
136		if !ok {
137			return ParsedModel{Family: "claude", Tier: TierUnknown, Raw: raw}
138		}
139		version, pre := parseVersionTokens(tokens[1:])
140		return ParsedModel{
141			Family:     "claude",
142			Version:    normalizeVersion(version),
143			Tier:       tier,
144			PreRelease: pre,
145			Raw:        raw,
146		}
147	}
148	
149	func parseClaudeShort(tierName string, tokens []string, raw string) ParsedModel {
150		tier := FamilyTiers["claude"][tierName]
151		version, pre := parseVersionTokens(tokens)
152		return ParsedModel{
153			Family:     "claude",
154			Version:    normalizeVersion(version),
155			Tier:       tier,
156			PreRelease: pre,
157			Raw:        raw,
158		}
159	}
160	
161	func parseGemini(tokens []string, raw string) ParsedModel {
162		if len(tokens) == 0 {
163			return ParsedModel{Family: "gemini", Tier: TierUnknown, Raw: raw}
164		}
165		version := parseDottedVersion(tokens[0])
166		if version == nil {
167			return ParsedModel{Family: "gemini", Tier: TierUnknown, Raw: raw}
168		}
169		remaining := append([]string(nil), tokens[1:]...)
170		preRelease := false
171		for len(remaining) > 0 && preReleaseSuffixes[remaining[len(remaining)-1]] {
172			preRelease = true
173			remaining = remaining[:len(remaining)-1]
174		}
175		tierName := strings.Join(remaining, "-")
176		tier, ok := FamilyTiers["gemini"][tierName]
177		if !ok {
178			tier = TierUnknown
179		}
180		return ParsedModel{
181			Family:     "gemini",
182			Version:    normalizeVersion(version),
183			Tier:       tier,
184			PreRelease: preRelease,
185			Raw:        raw,
186		}
187	}
188	
189	// parseDottedVersion parses a dotted version string like "5.5" or "5" into a slice.
190	// Returns nil if any component is not an integer.
191	func parseDottedVersion(s string) []int {
192		if s == "" {
193			return nil
194		}
195		parts := strings.Split(s, ".")
196		result := make([]int, 0, len(parts))
197		for _, p := range parts {
198			n, err := strconv.Atoi(p)
199			if err != nil {
200				return nil
201			}
202			result = append(result, n)
203		}
204		return result
205	}
206	
207	// parseVersionTokens extracts a version and pre-release flag from a token slice.
208	// Handles dotted tokens ("4.7") and consecutive hyphen-separated integers ("4", "7").
209	func parseVersionTokens(tokens []string) ([]int, bool) {
210		if len(tokens) == 0 {
211			return nil, false
212		}
213		preRelease := false
214		// If first token contains a dot, treat as a complete dotted version.
215		if strings.Contains(tokens[0], ".") {
216			if v := parseDottedVersion(tokens[0]); v != nil {
217				for _, t := range tokens[1:] {
218					if preReleaseSuffixes[t] {
219						preRelease = true
220					}
221				}
222				return v, preRelease
223			}
224		}
225		// Otherwise accumulate consecutive integer tokens (hyphenated version).
226		var version []int
227		for _, t := range tokens {
228			if preReleaseSuffixes[t] {
229				preRelease = true
230				continue
231			}
232			n, err := strconv.Atoi(t)
233			if err != nil {
234				break
235			}
236			version = append(version, n)
237		}
238		return version, preRelease
239	}
240	
241	// normalizeVersion pads a version slice to at least 2 components (major, minor).
242	func normalizeVersion(v []int) []int {
243		for len(v) < 2 {
244			v = append(v, 0)
245		}
246		return v
247	}
248	
249	// compareVersionSlices returns 1 if a > b, -1 if a < b, 0 if equal.
250	func compareVersionSlices(a, b []int) int {
251		n := len(a)
252		if len(b) > n {
253			n = len(b)
254		}
255		for i := range n {
256			av, bv := 0, 0
