1371	func serviceRoutingModelEligibility(entries []routing.HarnessEntry, cat *modelcatalog.Catalog) func(model string) (routing.ModelEligibility, bool) {
1372		if cat == nil {
1373			return nil
1374		}
1375		eligibility := make(map[string]routing.ModelEligibility)
1376	
1377		// mergeInto merges src into the eligibility map entry for key, or inserts
1378		// if absent. Called from both add and addShortAlias so alias entries receive
1379		// the same conservative merge semantics as primary entries.
1380		mergeInto := func(key string, src routing.ModelEligibility) {
1381			if existing, ok := eligibility[key]; ok {
1382				if src.Power > existing.Power {
1383					existing.Power = src.Power
1384				}
1385				existing.ExactPinOnly = existing.ExactPinOnly || src.ExactPinOnly
1386				existing.AutoRoutable = existing.AutoRoutable || src.AutoRoutable
1387				eligibility[key] = existing
1388				return
1389			}
1390			eligibility[key] = src
1391		}
1392	
1393		// addShortAlias also registers the bare tier-suffix alias (e.g. "haiku" for
1394		// "haiku-5.5" or "claude-haiku-5.5") in the eligibility map. This ensures
1395		// CheckPowerEligibility gates the bare alias correctly even when the
1396		// subscription-harness tier enrollment emits it before the catalog-surface
1397		// override can replace it with a versioned surface ID. Without this, a
1398		// lookup("haiku") returning ok=false would let the alias slip through the
1399		// exact_pin_only gate when the request carries no explicit power bounds.
1400		addShortAlias := func(modelID string, known routing.ModelEligibility) {
1401			parsed := modelcatalog.Parse(modelID)
1402			if parsed.Tier == modelcatalog.TierUnknown || parsed.Family == "" {
1403				return
1404			}
1405			tiers, ok := modelcatalog.FamilyTiers[parsed.Family]
1406			if !ok {
1407				return
1408			}
1409			for suffix, tier := range tiers {
1410				if tier == parsed.Tier && suffix != "" {
1411					mergeInto(suffix, known)
1412					break
1413				}
1414			}
1415		}
1416	
1417		add := func(modelID string, includeByDefault bool, status string) {
1418			modelID = strings.TrimSpace(modelID)
1419			if modelID == "" {
1420				return
1421			}
1422			view := modeleligibility.Resolve(modelID, includeByDefault, status, cat)
1423			known := routing.ModelEligibility{
1424				Power:        view.Power,
1425				ExactPinOnly: view.ExactPinOnly,
1426				AutoRoutable: view.AutoRoutable,
1427			}
1428			mergeInto(modelID, known)
1429			addShortAlias(modelID, eligibility[modelID])
1430		}
1431		for _, h := range entries {
1432			status := "available"
1433			if !h.Available {
1434				status = "unreachable"
1435			}
1436			if h.DefaultModel != "" {
1437				add(h.DefaultModel, true, status)
1438			}
1439			for _, modelID := range h.SupportedModels {
1440				add(modelID, true, status)
1441			}
1442			for _, p := range h.Providers {
1443				includeByDefault := !p.ExcludeFromDefaultRouting
1444				add(p.DefaultModel, includeByDefault, status)
1445				for _, modelID := range p.DiscoveredIDs {
1446					add(modelID, includeByDefault, status)
1447				}
1448			}
1449		}
1450		if len(eligibility) == 0 {
1451			return nil
1452		}
1453		return func(model string) (routing.ModelEligibility, bool) {
1454			known, ok := eligibility[strings.TrimSpace(model)]
1455			return known, ok
1456		}
1457	}
